#
# Versioned export script. The "Base" node gives the library a real version
# anchor (.gnu.version_d) while "global: *" keeps the exported symbol set
# unchanged: every symbol is still exported, only tagged with @@Base.
# Narrowing to an explicit whitelist together with "local: *;" will be done in
# a follow-up change that also covers every consumer of this library.

Base {
  global:
    *;
};
